//! Ownership-guarded publication, withdrawal, and freshness checks for agent types.

use std::path::{Path, PathBuf};

use super::{
    AGENT_TYPES_IGNORE_BODY, AGENT_TYPES_IGNORE_FIRST_LINE, AgentTypeBody, AgentTypeSpec,
    is_generated_agent_type, render_claude_agent_type,
};

specmark::scope!("spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES");

const IGNORE_FILE: &str = ".claude/agents/.gitignore";
const IGNORE_REASON: &str =
    "`.claude/agents/.gitignore` is missing or out of date, so this file is not kept out of Git";

/// Whether to publish generated files or only inspect their freshness.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[specmark::spec(documents = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub enum SyncMode {
    Write,
    Check,
}

/// The result for one declared agent type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[specmark::spec(documents = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub enum AgentTypeStatus {
    Created,
    Updated,
    Unchanged,
    Removed,
    Current,
    Stale,
    Missing,
    Foreign,
    Unavailable,
}

impl AgentTypeStatus {
    /// Stable lowercase spelling for presentation.
    #[specmark::spec(implements = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Created => "created",
            Self::Updated => "updated",
            Self::Unchanged => "unchanged",
            Self::Removed => "removed",
            Self::Current => "current",
            Self::Stale => "stale",
            Self::Missing => "missing",
            Self::Foreign => "foreign",
            Self::Unavailable => "unavailable",
        }
    }
}

/// Status and optional explanation, returned in the supplied spec order.
#[derive(Debug, Clone, PartialEq, Eq)]
#[specmark::spec(documents = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub struct AgentTypeOutcome {
    pub name: String,
    pub file: String,
    pub status: AgentTypeStatus,
    pub reason: Option<String>,
}

/// A refusal to publish without an owned ignore file, or a safe-filesystem error.
#[derive(Debug, thiserror::Error)]
#[specmark::spec(documents = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub enum AgentTypesError {
    #[error(
        "`{}` was not generated by vibe; vibe writes no subagent type without its own ignore file \
         (violates spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES; \
         fix: rename or delete it)",
        .path.display()
    )]
    ForeignIgnoreFile { path: PathBuf },
    #[error(
        "I/O error on `{}`: {reason} \
         (violates spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES; \
         fix: check that the directory is writable and not a link, then run `vibe prompt types` again)",
        .path.display()
    )]
    Io { path: PathBuf, reason: String },
}

/// Withdraw owned lane-bodied types when this launch delivers no project lane.
/// Absent and foreign files are left alone, as are package-bodied types and
/// the directory-local ignore file. No directories or files are created.
#[specmark::spec(implements = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub fn withdraw_lane_types(
    node_dir: &Path,
    specs: &[AgentTypeSpec],
) -> Result<Vec<AgentTypeOutcome>, AgentTypesError> {
    let io = |relative: &str, reason: String| AgentTypesError::Io {
        path: node_dir.join(relative),
        reason,
    };
    let project =
        vibe_safefs::Project::open(node_dir).map_err(|error| io("", format!("{error:#}")))?;
    let mut outcomes = Vec::new();
    for spec in specs {
        if !matches!(spec.body, AgentTypeBody::ProjectLane) {
            continue;
        }
        let file = spec.file();
        let existing = project
            .read_file(&file)
            .map_err(|error| io(&file, format!("{error:#}")))?;
        if existing.as_deref().is_some_and(is_generated_agent_type)
            && project
                .remove_file(&file)
                .map_err(|error| io(&file, format!("{error:#}")))?
        {
            outcomes.push(AgentTypeOutcome {
                name: spec.type_name(),
                file,
                status: AgentTypeStatus::Removed,
                reason: Some("this launch delivers no lane".to_owned()),
            });
        }
    }
    Ok(outcomes)
}

/// Resolve and inspect all declared types before validating the ignore guard,
/// then publish or report each type without touching authored or unknown files.
#[specmark::spec(implements = "spec://org.vibevm.core/vibevm/common/PROP-076#SYS-WORKER-TYPES")]
pub fn sync_agent_types(
    node_dir: &Path,
    specs: &[AgentTypeSpec],
    resolve: &dyn Fn(&AgentTypeBody) -> Result<Vec<u8>, String>,
    mode: SyncMode,
) -> Result<Vec<AgentTypeOutcome>, AgentTypesError> {
    let io = |relative: &str, reason: String| AgentTypesError::Io {
        path: node_dir.join(relative),
        reason,
    };
    let project =
        vibe_safefs::Project::open(node_dir).map_err(|error| io("", format!("{error:#}")))?;
    let mut inspected = Vec::with_capacity(specs.len());
    for spec in specs {
        let file = spec.file();
        let existing = project
            .read_file(&file)
            .map_err(|error| io(&file, format!("{error:#}")))?;
        inspected.push((existing, resolve(&spec.body)));
    }

    let mut ignore_current = false;
    if inspected.iter().any(|(_, resolved)| resolved.is_ok()) {
        let ignore = project
            .read_file(IGNORE_FILE)
            .map_err(|error| io(IGNORE_FILE, format!("{error:#}")))?;
        if let Some(bytes) = &ignore {
            let first = bytes
                .split(|byte| *byte == b'\n')
                .next()
                .unwrap_or_default();
            let first = first.strip_suffix(b"\r").unwrap_or(first);
            if first != AGENT_TYPES_IGNORE_FIRST_LINE.as_bytes() {
                return Err(AgentTypesError::ForeignIgnoreFile {
                    path: node_dir.join(IGNORE_FILE),
                });
            }
        }
        ignore_current = ignore.as_deref() == Some(AGENT_TYPES_IGNORE_BODY.as_bytes());
        if mode == SyncMode::Write && !ignore_current {
            project
                .write_atomic(IGNORE_FILE, AGENT_TYPES_IGNORE_BODY.as_bytes())
                .map_err(|error| io(IGNORE_FILE, format!("{error:#}")))?;
        }
    }

    let mut outcomes = Vec::with_capacity(specs.len());
    for (spec, (existing, resolved)) in specs.iter().zip(inspected) {
        let file = spec.file();
        let mut reason = None;
        let status = if existing
            .as_deref()
            .is_some_and(|bytes| !is_generated_agent_type(bytes))
        {
            AgentTypeStatus::Foreign
        } else {
            match resolved {
                Err(error) => {
                    reason = Some(error);
                    match (mode, existing.is_some()) {
                        (SyncMode::Write, true) => {
                            project
                                .remove_file(&file)
                                .map_err(|error| io(&file, format!("{error:#}")))?;
                            AgentTypeStatus::Removed
                        }
                        (SyncMode::Check, true) => AgentTypeStatus::Stale,
                        (_, false) => AgentTypeStatus::Unavailable,
                    }
                }
                Ok(body) => {
                    let desired = render_claude_agent_type(spec, &body);
                    match mode {
                        SyncMode::Write => {
                            if existing.as_deref() == Some(desired.as_slice()) {
                                AgentTypeStatus::Unchanged
                            } else {
                                project
                                    .write_atomic(&file, &desired)
                                    .map_err(|error| io(&file, format!("{error:#}")))?;
                                if existing.is_none() {
                                    AgentTypeStatus::Created
                                } else {
                                    AgentTypeStatus::Updated
                                }
                            }
                        }
                        SyncMode::Check => match existing {
                            None => AgentTypeStatus::Missing,
                            Some(bytes) if bytes != desired => AgentTypeStatus::Stale,
                            Some(_) if ignore_current => AgentTypeStatus::Current,
                            Some(_) => {
                                reason = Some(IGNORE_REASON.to_owned());
                                AgentTypeStatus::Stale
                            }
                        },
                    }
                }
            }
        };
        outcomes.push(AgentTypeOutcome {
            name: spec.type_name(),
            file,
            status,
            reason,
        });
    }
    Ok(outcomes)
}
